/* ---------- Memory panel ---------- */
/* each memory shows where it came from, as that source's own mark (Slack, Figma, GitHub, Notion, Linear, Drive) or an icon
   (something said in chat, an edit), and its kind in the kind's colour (--dm-k). A memory the agent learns arrives with a spinner
   on its mark and its words shimmering while it works the rule out, then a New tag (no tinted band, owner 18 Nov); the
   memories an answer uses pulse once with a quiet grey (never a hue) and say so. The card sits on two columns (owner, 18 Nov),
   its content 16px from every edge: the head's mark in a 28px column with each memory's mark centred under it, and the title,
   each memory and the footer's words 12px after it; a row's hover fill reaches 8px out round its content, and its Edit and
   Forget end on the content's right edge, under the filter. The panel keeps no room for the memory still to come: it grows as
   the new one opens its row (grow()) and stays centred in its stage */
.mmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-2);container:mmx/inline-size}
.mmx-h{display:flex;align-items:center;gap:8px 12px}
.mmx-ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.mmx-ht{flex:1 0 auto;min-width:0;font-size:14px;line-height:20px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mmx-tab button{font-size:12px;height:26px;padding:0 9px}
/* a narrow panel puts the filter on its own line under the title, from the content's left edge */
@container mmx (max-width:330px){.mmx-h{display:grid;grid-template-columns:28px minmax(0,1fr)}.mmx-tab{grid-column:1/-1;justify-self:start}}
/* a memory's mark sits on the head's tile column and its actions end on the content's 16px edge; its hover fill reaches 8px
   out round it, into the padding, in every style (owner, 26 Nov) */
.mmx-list{display:flex;flex-direction:column;margin:0 calc(-1 * var(--dm-s-2))}
.mmx-m{display:flex;align-items:flex-start;gap:12px;padding:var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;line-height:1.5;transition:background .3s}
@media (hover:hover) and (pointer:fine){.mmx-m:hover{background:var(--dm-row)}}
.mmx-src{width:28px;height:28px;margin-top:1px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;background:var(--dm-surface);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.mmx-src .brand{width:15px;height:15px;color:var(--dm-fg)}
.mmx-src .spin{width:12px;height:12px}
.mmx-b{flex:1;min-width:0;display:flex;flex-direction:column}
/* a memory that wraps never leaves one word alone on its last line (owner, 24 Nov) */
.mmx-b .t{text-wrap:pretty}
.mmx-m .t{outline:0;border-radius:var(--dm-r-tiny,5px);padding:0 3px;margin:0 -3px}
.mmx-m .t[contenteditable="true"]{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.mmx-m .t[contenteditable="true"]:focus{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* under it: its kind in the kind's colour, then where it came from */
.mmx-meta{display:flex;align-items:center;gap:6px;min-width:0;font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.mmx-meta>*{flex:none}
.mmx-meta .k{color:var(--dm-k);font-weight:500}
.mmx-meta .s{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis}
.mmx-meta .tag.nw{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-fg))}
.mmx-m .acts{display:flex;opacity:0;transition:opacity .2s}
.mmx-m:focus-within .acts{opacity:1}
@media (hover:hover) and (pointer:fine){.mmx-m:hover .acts{opacity:1}}
/* Forget's glyph ends on the content's edge, under the filter, its hover circle reaching out round it */
.mmx-m .ib{width:24px;height:24px}
.mmx-m .acts{margin-right:-6px}
.mmx-m.learn .acts{visibility:hidden}
/* a memory an answer uses pulses once with a quiet grey fill, and its source lifts */
.mmx-m.use{animation:mmxuse 1.4s var(--dm-ease)}
.mmx-m.use .mmx-src{animation:mmxlift .6s var(--dm-ease)}
@keyframes mmxuse{0%{background:var(--dm-hover)}100%{background:transparent}}
@keyframes mmxlift{40%{transform:translateY(-2px) scale(1.08)}}
/* a forgotten memory leaves a line with its Undo in its place: the words on the memories' mark column, Undo ending where their
   actions end */
.mmx-gone{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:32px;padding:4px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:12.5px;color:var(--dm-muted);background:var(--dm-chip)}
.mmx-gone span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mmx-gone button{flex:none;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;font-size:12.5px}
/* the line at the foot: how often the memory is used, or the answer it is helping with now; its mark centred in the memories'
   mark column and its words on their words column */
.mmx-f{display:flex;align-items:center;gap:12px;margin-top:var(--dm-s-1);padding:var(--dm-s-4) 0 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;line-height:18px;color:var(--dm-muted)}
.mmx-fi{display:grid;place-items:center;flex:none;width:28px;color:var(--dm-fg2)}
.mmx-fi .brand{width:14px;height:14px}
.mmx-ft{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mmx-ft.sw{display:block}
:root:not([data-style="soft"],[data-style="clean"]) .mmx-m.use:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:mmxusebp .9s steps(3,end)}
@keyframes mmxusebp{0%{background:var(--dm-hover)}100%{background:transparent}}
:root:not([data-style="soft"],[data-style="clean"]) .mmx-m.use .mmx-src:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:mmxbp .9s steps(1,end)}
@keyframes mmxbp{0%,50%{box-shadow:inset 0 0 0 1px var(--dm-line-strong)}51%,100%{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.mmx :is(.ib,.pill):active,:root[data-style="clean"] .mmx .ib:active,:root [data-style="clean"] .mmx .ib:active,:root [data-style="clean"].mmx .ib:active{transform:none}
/* Clean (owner, 18 Nov): the head's mark is the neutral tile with a hairline that the sources' marks have; the rows' fills are
   concentric with the card (14px, 8px in); an edited memory is a field with Clean's 10px corners; the footer is an off-white foot
   strip, edge to edge, its mark and words on the card's columns */
:root[data-style="clean"] .mmx-ic,:root [data-style="clean"] .mmx-ic,:root [data-style="clean"].mmx-ic{color:var(--dm-fg2);background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .mmx-src,:root [data-style="clean"] .mmx-src,:root [data-style="clean"].mmx-src{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] :is(.mmx-m,.mmx-gone),:root [data-style="clean"] :is(.mmx-m,.mmx-gone),:root [data-style="clean"]:is(.mmx-m,.mmx-gone){border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .mmx-m .t[contenteditable="true"],:root [data-style="clean"] .mmx-m .t[contenteditable="true"],:root [data-style="clean"].mmx-m .t[contenteditable="true"]{padding:1px 6px;margin:-1px -6px;border-radius:var(--dm-r-field)}
:root[data-style="clean"] .mmx-m .acts,:root [data-style="clean"] .mmx-m .acts,:root [data-style="clean"].mmx-m .acts{transition:opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .mmx-f,:root [data-style="clean"] .mmx-f,:root [data-style="clean"].mmx-f{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:var(--dm-s-1) calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:0 var(--dm-s-4);background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .mmx-m.use,:root [data-style="clean"] .mmx-m.use,:root [data-style="clean"].mmx-m.use{animation:mmxuse 1.4s var(--dm-ease)}

DM.def('memory-panel', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{book}', I('book')).replace('{spark}', I('spark','xs'));
  // where a memory came from: an app's own mark, or an icon for something said in chat or an edit
  const ICON = { chat:'comment', edit:'edit' };
  const mark = s => BRAND[s] || I(ICON[s] || s, 'xs');
  const KIND = { brand:['Brand', 'var(--dm-pl)'], process:['Process', 'var(--dm-pt)'] };
  let M = [
    ['brand','Primary buttons use the accent blue, never black','figma','Pricing review in Figma, Sep 12'],
    ['brand','Headlines stay under eight words','chat','You told the agent, Aug 30'],
    ['process','Ask Maya before publishing to the shared library','slack','A thread in #design-system, Sep 4'],
    ['brand','Card radius is 16px on web, 12px in the app','github','tokens.css on GitHub, Sep 18'],
    ['process','Run the launch checklist before every PR','notion','Launch checklist in Notion, Sep 20'],
    ['process','File design bugs in the Design QA project','linear','DES-214 in Linear, Sep 26'],
    ['brand','No em dashes in product copy','drive','Voice and tone guide in Drive, Oct 2']
  ].map((m, i) => ({ id:i, k:m[0], t:m[1], from:m[2], s:m[3] }));
  const list = $('.mmx-list', r), fi = $('.mmx-fi', r), ft = $('.mmx-ft', r);
  if (!r.closest('.ahx')) c.offs.push(hoverGlide(list, '.mmx-m'));
  let f = 'all', nid = 100;
  // the head names the panel only: a count of the memories and a row of their sources' marks repeated what the list shows
  const count = () => {};
  const meta = m => `<span class="k">${KIND[m.k][0]}</span><span aria-hidden="true">·</span><span class="s">${m.s}</span>${m.isNew ? '<span class="tag nw">New</span>' : ''}${m.used ? '<span class="tag nw">Used</span>' : ''}`;
  const rowOf = m => $(`.mmx-m[data-id="${m.id}"]`, list);
  function item(m){
    const el = html(`<div class="mmx-m${m.learn ? ' learn' : ''}" data-id="${m.id}" style="--dm-k:${KIND[m.k][1]}"><span class="mmx-src" aria-hidden="true">${m.learn ? '<span class="spin"></span>' : mark(m.from)}</span><span class="mmx-b"><span class="t${m.learn ? ' shim' : ''}" spellcheck="false">${m.t}</span><span class="mmx-meta">${meta(m)}</span></span><span class="acts"><button class="ib ed" aria-label="Edit" data-tip="Edit">${I('edit','xs')}</button><button class="ib rm" aria-label="Forget" data-tip="Forget">${I('trash','xs')}</button></span></div>`);
    const t = $('.t', el);
    $('.ed', el).onclick = () => { t.contentEditable = 'true'; t.focus({ preventScroll:true }); const s = document.getSelection(); s.selectAllChildren(t); s.collapseToEnd();
      const done = () => { t.contentEditable = 'false'; m.t = t.textContent.trim() || m.t; m.s = 'Edited by you, just now'; m.from = 'edit'; t.textContent = m.t; update(m); count(); };
      t.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } }; t.onblur = done; };
    $('.rm', el).onclick = () => { const i = M.indexOf(m); M.splice(i, 1); count();
      const g = html(`<div class="mmx-gone"><span>Forgot “${m.t.slice(0, 32)}${m.t.length > 32 ? '…' : ''}”</span><button>Undo</button></div>`); el.replaceWith(g); enter(g);
      const tm = setTimeout(() => { g.classList.add('leave'); setTimeout(() => g.remove(), 320); }, 4000);
      $('button', g).onclick = () => { clearTimeout(tm); M.splice(i, 0, m); count(); const n = item(m); g.replaceWith(n); enter(n); }; };
    return el;
  }
  // a memory's row catches up with its data: its source, its text once it has been learned, its tags and its highlight
  function update(m, pulse){
    const el = rowOf(m); if (!el) return;
    const src = $('.mmx-src', el), t = $('.t', el);
    if (!m.learn && el.classList.contains('learn')){ el.classList.remove('learn'); t.classList.remove('shim'); swap(t, m.t); src.innerHTML = mark(m.from); enter(src.firstElementChild); }
    else if (t.contentEditable !== 'true') src.innerHTML = mark(m.from);
    $('.mmx-meta', el).innerHTML = meta(m);
    if (pulse){ el.classList.remove('use'); void el.offsetWidth; el.classList.add('use'); }
  }
  function paint(){ list.innerHTML = ''; M.filter(m => f === 'all' || m.k === f).forEach(m => list.appendChild(item(m))); stagger([...list.children], 40); }
  // a row that arrives opens its own height, so the panel grows smoothly instead of jumping
  const growRow = el => { if (REDUCE) return; const cs = getComputedStyle(el), gap = parseFloat(getComputedStyle(list).rowGap) || 0, ease = getComputedStyle(r).getPropertyValue('--dm-ease').trim() || 'ease', blur = getComputedStyle(r).getPropertyValue('--dm-motion').trim() === 'clean' ? 0 : 4;
    el.animate([{ height:'0px', paddingTop:'0px', paddingBottom:'0px', marginBottom:-gap + 'px', opacity:0, filter:`blur(${blur}px)`, overflow:'hidden' }, { height:cs.height, paddingTop:cs.paddingTop, paddingBottom:cs.paddingBottom, marginBottom:'0px', opacity:1, filter:'blur(0px)', overflow:'hidden' }], { duration:560, easing:ease }); };
  seg($('.mmx-tab', r), v => { f = v; paint(); });
  count(); paint();
  // no room is kept for the memory still to come (owner, 17 Nov): the panel grows as the new one opens its row, and as a filter
  // or a forgotten memory changes the list (grow(), centred in its stage), once its entrance (which scales it) has ended
  const mroot = r.classList.contains('mmx') ? r : $('.mmx', r);
  if (mroot && r === c.st) Promise.resolve().then(() => Promise.all(mroot.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && mroot.isConnected) c.offs.push(grow(mroot)); });
  // the preview: the agent learns a rule from your edit in Figma, then drafts an email in Gmail with three memories, which
  // pulse as it reads them. Every state lives in the memories' data, so switching tabs keeps it; taking over settles it
  c.run(async () => {
    await c.step(2200);
    const m = { id:nid++, k:'brand', t:'Learning from your edit in Pricing v4', from:'figma', s:'Just now', learn:true };
    const learnt = () => Object.assign(m, { learn:false, t:'Use “Start free” instead of “Sign up” on CTAs', s:'Your edit in Pricing v4, just now' });
    c.taken(() => { if (m.learn){ learnt(); update(m); } if (ft.classList.contains('shim')){ ft.classList.remove('shim'); fi.innerHTML = I('spark','xs'); swap(ft, 'Used in 14 answers this week'); } });
    M.unshift(m); count(); if (f === 'brand' || f === 'all'){ const el = item(m); list.prepend(el); growRow(el); }
    await c.step(1500);
    learnt(); m.isNew = true; update(m);
    await c.step(2600);
    m.isNew = false; m.s = 'Your edit in Figma, today'; update(m);
    await c.step(1000);
    fi.innerHTML = BRAND.gmail; enter(fi.firstElementChild);
    ft.classList.add('shim'); swap(ft, 'Drafting the launch email in Gmail');
    await c.step(1100);
    let n = 0;
    for (const id of [m.id, 1, 6]){ const x = M.find(y => y.id === id); if (!x) continue; x.used = true; n++; update(x, true); await c.step(700); }
    ft.classList.remove('shim'); swap(ft, `Used ${n} ${n === 1 ? 'memory' : 'memories'} in the launch email draft`);
  });
});
